function design(hook, intuition, goals, algorithm, misconception, checks, vocabulary, bridges = []) {
  return { hook, intuition, goals: goals.split('|'), algorithm: algorithm.split('|'),
    misconception: { wrong: misconception[0], why: misconception[1], repair: misconception[2] },
    transfer: { prompt: checks.apply[0], explanation: checks.apply[4] }, checks,
    vocabulary: vocabulary.map(key => { const [term, definition, example] = terms[key]; return {term,definition,example}; }), bridges };
}

